function recentStoneImports20(w,tileId,days=240){const now=w.ordinalDay();let q=0;for(const e of w.telemetry?.entries||[])if(['TRADE','DOMESTIC_TRADE29'].includes(e.type)&&e.payload?.resource==='stone'&&(e.payload?.buyerTileId===tileId||e.payload?.toTileId===tileId)&&now-Number(e.ordinalDay||0)<=days)q+=Number(e.payload?.qty||0);return q;}
function nearbyQuarry20(v,w,tileId,r=4){return [...v.territory].map(id=>w.map.get(id)).some(t=>t&&w.map.distance(tileId,t.id)<=r&&activeQuarrySlots(t)>0&&Number(t.ratio?.('stone',w.ordinalDay())||0)>.015);}
const startConstruction19=NS.Village.prototype.startConstruction;
NS.Village.prototype.startConstruction=function(w,tileId,type,reason='AI'){
 if(type==='stoneworks'){
  if(NS.V030B3?.stoneworksEligibility){const e=NS.V030B3.stoneworksEligibility(this,w,tileId);if(!e.ok)return false;}else{const t=w.map.get(tileId);if(!t)return false;const works=[...this.territory].map(id=>w.map.get(id)).reduce((n,x)=>n+(x?.buildings?.includes('stoneworks')?1:0),0),quarries=[...this.territory].map(id=>w.map.get(id)).reduce((n,x)=>n+(activeQuarrySlots(x)>0?1:0),0),maxWorks=Math.max(1,Math.ceil(quarries/3)+(this.population()>=120?1:0));if(works>=maxWorks)return false;const cons=recentConstruction20(w,this,tileId),imports=recentStoneImports20(w,tileId),upstream=nearbyQuarry20(this,w,tileId);if(cons<2||(!upstream&&imports<18))return false;}
 }
 return startConstruction19.call(this,w,tileId,type,reason);
};

