function statsRows20(ui){const scope=ui.statsScope||'nation',metric=ui.statsMetric||'population',period=Number(ui.statsPeriod||0),now=ui.world.year,key=METRIC20[scope]?.[metric]?.[1];let rows=[];if(scope==='world')rows=(ui.world.telemetry.yearlySummaries||[]).map(x=>({year:x.year,value:x.global?.[key]}));else if(scope==='nation'){const id=Number(ui.statsNationId??ui.world.selectedVillageId);rows=(ui.world.telemetry.yearlySummaries||[]).map(x=>({year:x.year,value:(x.nations||[]).find(n=>n.id===id)?.[key]}));}else{const id=Number(ui.statsNationId??ui.world.selectedVillageId),tile=Number(ui.statsSettlementId??ui.world.selectedTileId);rows=(ui.world.telemetry.settlementYearly?.[`${id}:${tile}`]||[]).map(x=>({year:x.y,value:x[key]}));}rows=rows.filter(r=>Number.isFinite(Number(r.value))).map(r=>({year:Number(r.year),value:Number(r.value)}));if(period>0)rows=rows.filter(r=>r.year>=Math.max(1,now-period+1));return rows;}
function setOptionsIfChanged(el,signature,html){if(!el)return;if(el.dataset.v20Sig!==signature){el.innerHTML=html;el.dataset.v20Sig=signature;}}
function syncStats20(ui){const scope=ui.q('statsScope'),nation=ui.q('statsNation'),settle=ui.q('statsSettlement'),metric=ui.q('statsMetric'),period=ui.q('statsPeriod');if(!scope)return;ui.statsScope=ui.statsScope||'nation';ui.statsNationId=ui.statsNationId??ui.world.selectedVillageId;scope.value=ui.statsScope;const nSig=ui.world.villages.map(v=>`${v.id}:${v.name}`).join('|');setOptionsIfChanged(nation,nSig,ui.world.villages.map(v=>`<option value="${v.id}">${v.name}</option>`).join(''));if(!ui.world.villages.some(v=>v.id===Number(ui.statsNationId)))ui.statsNationId=ui.world.selectedVillageId;nation.value=String(ui.statsNationId);const v=ui.world.villages.find(x=>x.id===Number(ui.statsNationId))||ui.world.selectedNation,ids=v?[...v.territory]:[],sSig=`${v?.id}:${ids.join(',')}`;setOptionsIfChanged(settle,sSig,ids.map(id=>{const t=ui.world.map.get(id);return`<option value="${id}">(${t?.x},${t?.y})${id===v?.coreTileId?' 중심지':''}</option>`}).join(''));if(!ids.includes(Number(ui.statsSettlementId)))ui.statsSettlementId=ids.includes(ui.world.selectedTileId)?ui.world.selectedTileId:ids[0];if(ui.statsSettlementId!=null)settle.value=String(ui.statsSettlementId);const opts=METRIC20[ui.statsScope]||METRIC20.nation,mSig=ui.statsScope+':'+Object.keys(opts).join(',');setOptionsIfChanged(metric,mSig,Object.entries(opts).map(([k,x])=>`<option value="${k}">${x[0]}</option>`).join(''));if(!opts[ui.statsMetric])ui.statsMetric='population';metric.value=ui.statsMetric;period.value=String(ui.statsPeriod||0);nation.style.display=ui.statsScope==='world'?'none':'';settle.style.display=ui.statsScope==='settlement'?'':'none';const note=ui.q('statsNote');if(note)note.textContent=ui.statsScope==='settlement'?'가격은 해당 정착지의 현지 시세입니다. Gold는 국가 단위라 정착지 Gold 그래프는 없습니다.':'가격 그래프는 관찰자가 계산한 국가/세계 평균입니다. 각 문명이 이 평균을 전지적으로 아는 것은 아닙니다.';}
function drawStats20(ui){const canvas=ui.q('statsCanvas');if(!canvas)return;const wrap=canvas.parentElement,w=Math.max(300,Math.min(920,wrap?.clientWidth||760)),h=350,dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.width=w+'px';canvas.style.height=h+'px';const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const rows=statsRows20(ui),scope=ui.statsScope||'nation',label=(METRIC20[scope]?.[ui.statsMetric||'population']||['값'])[0],pad={l:58,r:18,t:24,b:38};ctx.font='12px system-ui';ctx.fillStyle='#93a6bf';if(!rows.length){ctx.fillText('이 조건에서 표시할 연간 기록이 없습니다.',24,45);return;}let min=Math.min(...rows.map(x=>x.value)),max=Math.max(...rows.map(x=>x.value));if(min===max){min=Math.max(0,min-1);max+=1;}const margin=(max-min)*.08||1;min=Math.max(0,min-margin);max+=margin;const x0=pad.l,cw=w-pad.l-pad.r,ch=h-pad.t-pad.b,xf=y=>rows.length===1?x0+cw/2:x0+(y-rows[0].year)/(rows.at(-1).year-rows[0].year||1)*cw,yf=v=>pad.t+(max-v)/(max-min)*ch;ctx.strokeStyle='#2a3d58';for(let i=0;i<=4;i++){const y=pad.t+ch*i/4,val=max-(max-min)*i/4;ctx.beginPath();ctx.moveTo(x0,y);ctx.lineTo(x0+cw,y);ctx.stroke();ctx.fillStyle='#93a6bf';ctx.textAlign='right';ctx.fillText(Math.abs(val)>=1000?Math.round(val).toLocaleString():val.toFixed(Math.abs(max-min)<10?2:1),x0-7,y+4);}ctx.strokeStyle='#69adff';ctx.lineWidth=2.5;ctx.beginPath();rows.forEach((r,i)=>{const x=xf(r.year),y=yf(r.value);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();ctx.fillStyle='#eef5ff';ctx.textAlign='left';ctx.font='700 13px system-ui';ctx.fillText(label,pad.l,pad.t-7);ctx.font='11px system-ui';ctx.fillStyle='#93a6bf';ctx.textAlign='center';for(const i of [0,Math.floor((rows.length-1)/2),rows.length-1].filter((v,i,a)=>a.indexOf(v)===i))ctx.fillText(`${rows[i].year}년`,xf(rows[i].year),h-14);const last=rows.at(-1);ctx.fillStyle='#eef5ff';ctx.textAlign='right';ctx.fillText(`최근 ${last.year}년 · ${last.value.toLocaleString(undefined,{maximumFractionDigits:3})}`,w-pad.r,pad.t-7);}

/* ---------- Population structure observer UI ---------- */
function peopleForSocial(ui,v){const sid=ui.socialSettlementId;if(sid==null||sid==='all')return v.residents.filter(p=>p.alive);return v.residents.filter(p=>p.alive&&p.homeTileId===Number(sid));}
function socialHTML(ui,v){const ids=[...v.territory],selected=ui.socialSettlementId??'all',options=`<option value="all">국가 전체</option>`+ids.map(id=>{const t=ui.world.map.get(id);return`<option value="${id}">(${t?.x},${t?.y})${id===v.coreTileId?' 중심지':''}</option>`}).join('');return`<div class="section-head"><div><h2>${v.name} 인구 구조</h2><div class="small muted">실제 Person 개체의 나이·성별·직업을 집계합니다.</div></div><select id="v20SocialSettlement">${options}</select></div><div id="v20SocialBody"></div>`;}
function updateSocialBody(ui,v){const body=ui.q('v20SocialBody');if(!body)return;const ps=peopleForSocial(ui,v),male=ps.filter(p=>p.sex==='남').length,female=ps.filter(p=>p.sex==='여').length,total=Math.max(1,ps.length),jobs=new Map();for(const p of ps)jobs.set(p.job,(jobs.get(p.job)||0)+1);const jobRows=[...jobs.entries()].sort((a,b)=>b[1]-a[1]),jmax=Math.max(1,...jobRows.map(x=>x[1])),bins=[];for(let a=0;a<80;a+=10)bins.push({label:`${a}~${a+9}`,m:0,f:0});bins.push({label:'80+',m:0,f:0});for(const p of ps){const i=Math.min(8,Math.floor(p.age/10));if(p.sex==='남')bins[i].m++;else bins[i].f++;}const amax=Math.max(1,...bins.flatMap(x=>[x.m,x.f])),commuters=ps.filter(p=>p.age>=15&&ensurePerson20(p).workTileId!=null&&p.workTileId!==p.homeTileId).length,miners=ps.filter(p=>p.job==='광부').length;body.innerHTML=`<div class="v20-social-summary"><div class="v20-donut" style="--male:${male/total*360}deg"><div><strong>${ps.length}</strong><span>명</span></div></div><div><strong>성별</strong><div class="small">♂ 남성 ${male}명 (${(male/total*100).toFixed(1)}%)</div><div class="small">♀ 여성 ${female}명 (${(female/total*100).toFixed(1)}%)</div><div class="small muted">통근 ${commuters}명 · 광부 ${miners}명</div></div></div><h3>인구 피라미드</h3><div class="v20-pyramid">${bins.map(b=>`<div class="v20-age-row"><span class="v20-age-num">${b.m}</span><div class="v20-age-side left"><i style="width:${b.m/amax*100}%"></i></div><strong>${b.label}</strong><div class="v20-age-side right"><i style="width:${b.f/amax*100}%"></i></div><span class="v20-age-num">${b.f}</span></div>`).join('')}<div class="v20-pyr-label"><span>남성</span><span>여성</span></div></div><h3>직업 분포</h3><div class="v20-jobs">${jobRows.map(([job,n])=>`<div class="v20-job"><span>${job}</span><div class="bar"><i style="width:${n/jmax*100}%"></i></div><strong>${n}</strong></div>`).join('')||'<div class="muted">주민 없음</div>'}</div>`;}

