const snap19=NS.Telemetry.prototype.snapshot;
NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){const s=snap19.call(this,w,reason,note);for(const r of s.villages||[]){const v=w.villages.find(x=>x.id===r.id);if(!v)continue;ensureNation20(v);const commuters=v.residents.filter(p=>p.alive&&p.age>=15&&ensurePerson20(p).workTileId!==p.homeTileId).length,quarrySlots=[...v.territory].map(id=>w.map.get(id)).reduce((n,t)=>n+activeQuarrySlots(t),0),quarryWorkers=v.residents.filter(p=>p.alive&&p.job==='광부'&&activeQuarrySlots(w.map.get(ensurePerson20(p).workTileId))>0).length;r.frontierProjects=v.frontierProjects.length;r.frontierProjectCap=maxFrontierProjects(v);r.commuters=commuters;r.quarryWorkerSlots=quarrySlots;r.quarryWorkers=quarryWorkers;}return s;};
