NS.Telemetry.prototype.snapshotsCSV=function(){const extra=['frontierProjects','frontierProjectCap','commuters','quarryWorkerSlots','quarryWorkers'],base=csv19.call(this),lines=base.split('\n');if(!lines.length)return base;const esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+extra.map(esc).join(',');let i=1;for(const s of this.snapshots||[])for(const v of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+extra.map(k=>esc(v[k])).join(',');}return lines.join('\n');};
const json19=NS.Telemetry.prototype.toJSON;
NS.Telemetry.prototype.toJSON=function(w){const d=json19.call(this,w);d.version='0.20';d.worldSummary.populationStructure='observer UI: age pyramid, sex ratio, occupation distribution at nation/settlement scope';d.worldSummary.workplaceModel='Person homeTileId and workTileId separated; nearby job sites can employ commuters';d.worldSummary.frontierModel='populated settlements can launch parallel local frontier projects with real pioneers';d.worldSummary.stoneContinuity='quarry employment slots recruit real miners; stoneworks requires construction demand plus upstream stone flow';d.worldSummary.statsUI='selectors are preserved across ticks; graph updates without rebuilding open select options';return d;};
