 NS.UI.prototype.bind=function(){bind19.call(this);const tabs=this.q('villageSubtabs');if(tabs&&!tabs.querySelector('[data-sub="social"]')){const b=document.createElement('button');b.dataset.sub='social';b.textContent='사회';b.onclick=()=>{this.sub='social';this.socialSettlementId='all';this.renderVillageContent();document.querySelectorAll('#villageSubtabs button').forEach(x=>x.classList.toggle('active',x.dataset.sub===this.sub));};tabs.appendChild(b);}};
